//! The generators: a height field (and an ink field) per kind, turned into the tile layout of the crate docs.
//! PLACEHOLDER (lead, K59 skeleton): plain fBm for every kind and simple rulings — card W31-texture-gen replaces this
//! with real materials.

use crate::noise::fbm;
use crate::{Kind, Params, Tile};

/// Bumped whenever the generated bytes change, so cached tiles of an older generator are not reused.
pub const VERSION: u32 = 0;

/// Logical size of one tile.
const LOGICAL: f32 = 480.0;

pub fn generate(p: &Params) -> Tile {
    let size = ((LOGICAL * p.device_scale.max(1.0)).round() as u32).max(16);
    let n = size as usize;
    let mut height = vec![0f32; n * n];
    let mut ink = vec![0f32; n * n];
    let seed = p.kind as u64 * 1013 + 17;
    for y in 0..n {
        for x in 0..n {
            let (u, v) = (x as f32 / size as f32, y as f32 / size as f32);
            let mut h = fbm(u, v, 48, 4, seed);
            h += p.wrinkles * (fbm(u, v, 3, 3, seed ^ 0xABCD) - 0.5) * 4.0;
            let ruled = rulings(p.kind, u * LOGICAL, v * LOGICAL);
            if p.tint {
                ink[y * n + x] = ruled;
            } else {
                h -= ruled * 0.6;
            }
            height[y * n + x] = h;
        }
    }
    let depth = 6.0 * p.device_scale.max(1.0);
    let mut rgba = vec![0u8; n * n * 4];
    let at = |x: isize, y: isize| height[(y.rem_euclid(n as isize) as usize) * n + x.rem_euclid(n as isize) as usize];
    let mean = height.iter().sum::<f32>() / height.len() as f32;
    let spread = height.iter().map(|h| (h - mean).abs()).fold(1e-6, f32::max);
    for y in 0..n {
        for x in 0..n {
            let (xi, yi) = (x as isize, y as isize);
            let dx = (at(xi + 1, yi) - at(xi - 1, yi)) * depth;
            let dy = (at(xi, yi + 1) - at(xi, yi - 1)) * depth;
            let l = (dx * dx + dy * dy + 1.0).sqrt();
            let (nx, ny) = (-dx / l, -dy / l);
            let i = (y * n + x) * 4;
            rgba[i] = enc(nx);
            rgba[i + 1] = enc(ny);
            rgba[i + 2] = enc((height[y * n + x] - mean) / spread);
            rgba[i + 3] = (ink[y * n + x].clamp(0.0, 1.0) * 255.0).round() as u8;
        }
    }
    Tile {
        size,
        logical: LOGICAL,
        rgba,
    }
}

fn enc(v: f32) -> u8 {
    ((v.clamp(-1.0, 1.0) * 0.5 + 0.5) * 255.0).round() as u8
}

/// Rulings at logical position (x, y): 1 on a line or dot, 0 off it (24 px pitch, 480 = 20 pitches).
fn rulings(kind: Kind, x: f32, y: f32) -> f32 {
    let pitch = 24.0;
    let d = |v: f32| (v.rem_euclid(pitch) - pitch / 2.0).abs();
    let line = |dist: f32| (1.0 - (dist - 0.4).max(0.0)).clamp(0.0, 1.0);
    match kind {
        Kind::PaperDots => {
            let r = (d(x) * d(x) + d(y) * d(y)).sqrt();
            (1.6 - r).clamp(0.0, 1.0)
        }
        Kind::PaperLines => line(d(y)),
        Kind::PaperGrid => line(d(x)).max(line(d(y))),
        _ => 0.0,
    }
}
